<template>
  <div class="purchase-modal" @click="$emit('close')">
    <div class="modal-content" @click.stop>
      <div class="modal-header">
        <div class="header-content">
          <div class="coming-soon-notice">
            <i class="fas fa-clock"></i>
            Pre-order will be available soon
          </div>
          <h2>Complete Your Pre-order</h2>
        </div>
        <button class="close-button" @click="$emit('close')">×</button>
      </div>

      <div class="modal-body">
        <div class="product-summary">
          <h3>{{ product.name }}</h3>
          <p class="price">{{ product.price }}</p>
          <p class="payment-method">
            <i class="fas fa-coins"></i> Payment: {{ product.paymentMethod }}
          </p>
        </div>

        <form @submit.prevent="handleSubmit" class="purchase-form">
          <div class="form-section">
            <h4><i class="fas fa-shipping-fast"></i> Delivery Address</h4>
            
            <div class="form-group">
              <label for="fullName">Full Name *</label>
              <input 
                id="fullName"
                v-model="formData.fullName" 
                type="text" 
                required 
                placeholder="Enter your full name"
              >
            </div>

            <div class="form-row">
              <div class="form-group">
                <label for="country">Country *</label>
                <select id="country" v-model="formData.country" required>
                  <option value="">Select Country</option>
                  <option value="US">United States</option>
                  <option value="CA">Canada</option>
                  <option value="UK">United Kingdom</option>
                  <option value="DE">Germany</option>
                  <option value="FR">France</option>
                  <option value="AU">Australia</option>
                  <option value="JP">Japan</option>
                  <option value="OTHER">Other</option>
                </select>
              </div>
              <div class="form-group">
                <label for="city">City *</label>
                <input 
                  id="city"
                  v-model="formData.city" 
                  type="text" 
                  required 
                  placeholder="Enter your city"
                >
              </div>
            </div>

            <!-- Custom country input when "Other" is selected -->
            <div v-if="formData.country === 'OTHER'" class="form-group">
              <label for="customCountry">Specify Country *</label>
              <input 
                id="customCountry"
                v-model="formData.customCountry" 
                type="text" 
                required 
                placeholder="Enter your country name"
              >
            </div>

            <div class="form-group">
              <label for="address">Street Address *</label>
              <input 
                id="address"
                v-model="formData.address" 
                type="text" 
                required 
                placeholder="Enter your street address"
              >
            </div>

            <div class="form-row">
              <div class="form-group">
                <label for="postalCode">Postal Code *</label>
                <input 
                  id="postalCode"
                  v-model="formData.postalCode" 
                  type="text" 
                  required 
                  placeholder="Postal code"
                >
              </div>
              <div class="form-group">
                <label for="phone">Phone Number</label>
                <input 
                  id="phone"
                  v-model="formData.phone" 
                  type="tel" 
                  placeholder="Optional"
                >
              </div>
            </div>
          </div>

          <div class="form-section">
            <h4><i class="fas fa-wallet"></i> Token Holdings</h4>
            <div class="token-info">
              <p>Your BITCAT tokens will determine the final price</p>
              <div class="token-status">
                <i class="fas fa-info-circle"></i>
                Connect your wallet during checkout to verify token holdings
              </div>
            </div>
          </div>

          <div class="form-actions">
            <button type="button" @click="$emit('close')" class="cancel-button">
              Cancel
            </button>
            <button type="submit" class="confirm-button" disabled>
              <i class="fas fa-clock"></i>
              Pre-order Opens Soon
            </button>
          </div>
        </form>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref } from 'vue'

const props = defineProps({
  product: {
    type: Object,
    required: true
  }
})

const emit = defineEmits(['close', 'confirm'])

const formData = ref({
  fullName: '',
  country: '',
  customCountry: '',
  city: '',
  address: '',
  postalCode: '',
  phone: ''
})

const handleSubmit = () => {
  // Basic validation
  const required = ['fullName', 'country', 'city', 'address', 'postalCode']
  let isValid = required.every(field => formData.value[field].trim())
  
  // Additional validation for custom country
  if (formData.value.country === 'OTHER' && !formData.value.customCountry.trim()) {
    isValid = false
  }
  
  if (!isValid) {
    alert('Please fill in all required fields')
    return
  }

  // Prepare delivery address data
  const deliveryData = { ...formData.value }
  
  // If "Other" country selected, use custom country as the country
  if (formData.value.country === 'OTHER' && formData.value.customCountry) {
    deliveryData.country = formData.value.customCountry
  }

  // Emit purchase data
  emit('confirm', {
    product: props.product,
    deliveryAddress: deliveryData,
    timestamp: new Date().toISOString()
  })
}
</script>

