<template>
  <div class="product-page">
    <div class="container">
      <!-- Navigation back -->
      <div class="breadcrumb">
        <router-link to="/store" class="breadcrumb-link"><i class="fas fa-arrow-left"></i> Back to Store</router-link>
      </div>

      <div v-if="product" class="product-content">
        <ProductGallery 
          :image="product.image" 
          :alt="product.name"
          @open-modal="openImageModal" 
        />
        
        <ProductInfo 
          :product="product"
          @purchase="handlePurchase"
        />
      </div>

      <!-- Shipping Information - shown for all products -->
      <ShippingInfo v-if="product" />

      <div v-else class="not-found">
        <h1>Product Not Found</h1>
        <p>The requested product could not be found.</p>
        <router-link to="/store" class="back-link">← Back to Store</router-link>
      </div>
    </div>

    <!-- Image modal -->
    <ImageModal 
      v-if="showImageModal" 
      :image="product?.image" 
      :alt="product?.name"
      @close="closeImageModal" 
    />

    <!-- Purchase modal -->
    <PurchaseModal
      v-if="showPurchaseModal"
      :product="product"
      @close="closePurchaseModal"
      @confirm="confirmPurchase"
    />
  </div>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRoute } from 'vue-router'
import ProductGallery from '@/components/store/ProductGallery.vue'
import ProductInfo from '@/components/store/ProductInfo.vue'
import ImageModal from '@/components/store/ImageModal.vue'
import PurchaseModal from '@/components/store/PurchaseModal.vue'
import ShippingInfo from '@/components/store/ShippingInfo.vue'

const route = useRoute()
const showImageModal = ref(false)
const showPurchaseModal = ref(false)

// Product data - local JSON structure
const productsData = {
  toy: {
    id: 'toy',
    name: 'BITCAT Plush Toy',
    price: '$6 - $14',
    priceNote: 'Price depends on your token holdings',
    image: 'https://bitcat.fun/data/BITCAT-toy.jpg',
    status: 'Pre-order Coming Soon',
    launchDate: 'Coming soon',
    shortDescription: 'A soft and compact BITCAT plush toy - the perfect souvenir for cat lovers and BITCAT fans. This adorable collectible brings the charm of BITCAT into the real world.',
    description: {
      title: 'Product Details',
      features: [
        'High-quality BITCAT plush toy',
        'Official merchandise with original design',
        'Limited edition for token holders',
        'Payment exclusively in BITCAT tokens',
        'Dynamic pricing based on token holdings'
      ],
      note: 'The actual product may differ slightly from the image, but will correspond to the original BITCAT design.'
    },
    exclusive: true,
    paymentMethod: 'BITCAT Tokens'
  }
}

// Get current product based on route parameter
const product = computed(() => {
  const itemId = route.params.item
  return productsData[itemId] || null
})

const openImageModal = () => {
  showImageModal.value = true
  document.body.style.overflow = 'hidden'
}

const closeImageModal = () => {
  showImageModal.value = false
  document.body.style.overflow = 'auto'
}

const handlePurchase = () => {
  showPurchaseModal.value = true
}

const closePurchaseModal = () => {
  showPurchaseModal.value = false
}

const confirmPurchase = (purchaseData) => {
  // Handle purchase confirmation
  console.log('Purchase confirmed:', purchaseData)
  // TODO: Implement actual purchase logic
  closePurchaseModal()
}

const handleEscKey = (event) => {
  if (event.key === 'Escape') {
    if (showImageModal.value) {
      closeImageModal()
    }
    if (showPurchaseModal.value) {
      closePurchaseModal()
    }
  }
}

onMounted(() => {
  // Title is not changed for product pages
  document.addEventListener('keydown', handleEscKey)
})

onUnmounted(() => {
  document.removeEventListener('keydown', handleEscKey)
  document.body.style.overflow = 'auto'
})
</script>

